#!/bin/bash
# Experiment 06 — simulate the CosmoGrid density shells (nside 2048) at DES Y3 depth.
# float64. A 2x2 grid: {2-bin, 3-bin} source depth x {full sky, big quadrant} observer.
#
# The geometry (boxes, meshes, observers, GPU layout, CosmoGrid shell a-edges) is GENERATED by
# prep_geometry.py into geometry.sh — run that first, then this:
#     python prep_geometry.py        # writes geometry.sh + assets/exp06-geometry.svg
#     MODE=dryrun bash run.sh        # print the four resolved fli-launcher commands
#     bash run.sh                    # submit to SLURM
#
# Wall-times below are first-guess estimates — tune after the first run.
source "$(dirname "$0")/../_launch_common.sh"
source "$(dirname "$0")/geometry.sh"

echo "### Exp 06 — CosmoGrid-matched density shells  (MODE=$MODE)"

# Shared physics: BullFrog (bf) 50-step PM; TSC paint + force-window deconvolution; nearest-grid-point
# (ngp) spherical painting at nside 2048 (== CosmoGrid); CosmoGrid fiducial cosmology ($COSMO); float64.
# pdim "(devices, 1)" shards the spherical npix over the first (M) axis (~72 MB/device at nside 2048),
# so the lightcone output adds negligibly to the 2560^3 float64 mesh.
COMMON="--sim-mode pm --solver bf --nb-steps 50 --paint-order tsc --deconvolution \
  --nside 2048 --scheme ngp --enable-x64 --seed $SEED $COSMO"

# --- 2-bin set (DES Y3 bins 1+2, z <= 0.82) -----------------------------------------------------
launch $NODES_FULL 4 $PDIM_FULL 06:00:00 -- $COMMON \
  --mesh-size $MESH_FULL --box-size $BOX_2BIN_FULL --observer-position $OBS_FULL \
  --ts-near $TS_NEAR_2BIN --ts-far $TS_FAR_2BIN \
  --output "$RESULTS/exp6/cosmogrid_2bin_fullsky.parquet" --name "exp6_2bin_fullsky_s%seed%"

launch $NODES_QUAD 4 $PDIM_QUAD 04:00:00 -- $COMMON \
  --mesh-size $MESH_QUAD --box-size $BOX_2BIN_QUAD --observer-position $OBS_QUAD \
  --ts-near $TS_NEAR_2BIN --ts-far $TS_FAR_2BIN \
  --output "$RESULTS/exp6/cosmogrid_2bin_quadrant.parquet" --name "exp6_2bin_quadrant_s%seed%"

# --- 3-bin set (DES Y3 bins 1+2+3, z <= 1.06) ---------------------------------------------------
launch $NODES_FULL 4 $PDIM_FULL 06:00:00 -- $COMMON \
  --mesh-size $MESH_FULL --box-size $BOX_3BIN_FULL --observer-position $OBS_FULL \
  --ts-near $TS_NEAR_3BIN --ts-far $TS_FAR_3BIN \
  --output "$RESULTS/exp6/cosmogrid_3bin_fullsky.parquet" --name "exp6_3bin_fullsky_s%seed%"

launch $NODES_QUAD 4 $PDIM_QUAD 04:00:00 -- $COMMON \
  --mesh-size $MESH_QUAD --box-size $BOX_3BIN_QUAD --observer-position $OBS_QUAD \
  --ts-near $TS_NEAR_3BIN --ts-far $TS_FAR_3BIN \
  --output "$RESULTS/exp6/cosmogrid_3bin_quadrant.parquet" --name "exp6_3bin_quadrant_s%seed%"
